function Navbar() {
  return (
    <nav className="navbar">
      <h2 className="nav-logo">My Gallery</h2>

      <ul className="nav-links">
        <li>Home</li>
        <li>Gallery</li>
        <li>Contact</li>
      </ul>
    </nav>
  );
}

export default Navbar;
